const temp = toNumberOrNull(p.temperatura_C ?? p.temperatura_c ?? p.temperatura ?? p.temp);
const gasRaw = toNumberOrNull(p.mq135_aire ?? p.gas ?? p.mq135);

const tsIso = normalizeTimestamp(p.timestamp ?? p.timestamp_origen ?? p.ts);

const TEMP_MIN_C = -20;
const TEMP_MAX_C = 80;
const MQ135_RAW_MIN = 0;
const MQ135_RAW_MAX = 4095;
const MQ135_PPM_MAX = 120;

const errors = [];
const categories = new Set();

function addError(code, category) {
    if (code && !errors.includes(code)) {
        errors.push(code);
    }
    if (category) categories.add(category);
}

if (!deviceIdRaw) {
    addError("device_id_faltante", "INCOMPLETO");
}
if (!zonaRaw) {
    addError("zona_faltante", "INCOMPLETO");
}
if (!tsIso) {
    addError("timestamp_invalido", "FORMATO");
}

if (temp === null) {
    addError("temperatura_incompleta", "INCOMPLETO");
} else if (temp < TEMP_MIN_C || temp > TEMP_MAX_C) {
    addError("temperatura_fuera_rango", "ATIPICO");
}

if (gasRaw === null) {
    addError("mq135_incompleto", "INCOMPLETO");
} else if (gasRaw < MQ135_RAW_MIN || gasRaw > MQ135_RAW_MAX) {
    addError("mq135_fuera_rango", "ATIPICO");
}

const gasPpm = Number.isFinite(gasRaw) ? mapRawToPpm(gasRaw, MQ135_RAW_MIN, MQ135_RAW_MAX, MQ135_PPM_MAX) : null;

let tipo = "OK";
if (errors.length) {
    const cats = Array.from(categories);
    tipo = cats.length > 1 ? "MULTIPLE" : (cats[0] || "ERROR");
}

msg.payload = {
    device_id: deviceId,
    zona,
    temperatura_C: temp,
    mq135_aire: gasRaw,
    mq135_ppm: gasPpm,
    timestamp: tsIso || p.timestamp
};

msg.validation = {
    hasErrors: errors.length > 0,
    tipo,
    errors,
    detalle: errors.join("; "),
    valor: {
        temperatura_C: temp,
        mq135_aire: gasRaw,
        timestamp: tsIso || p.timestamp
    }
};

return [msg, null];

