function toDate(raw) {
    const dt = new Date(raw);
    return Number.isFinite(dt.getTime()) ? dt : null;
}

function round(value, digits = 2) {
    return Number.isFinite(value) ? Number(value.toFixed(digits)) : null;
}

function mean(arr) {
    if (!arr.length) return null;
    return arr.reduce((sum, v) => sum + v, 0) / arr.length;
}

function variance(arr, avg) {
    if (!arr.length) return null;
    const m = Number.isFinite(avg) ? avg : mean(arr);
    if (!Number.isFinite(m)) return null;
    return arr.reduce((sum, v) => sum + Math.pow(v - m, 2), 0) / arr.length;
}

function stddev(arr, avg) {
    const v = variance(arr, avg);
    return Number.isFinite(v) ? Math.sqrt(v) : null;
}

function sorted(arr) {
    return arr.slice().sort((a, b) => a - b);
}

function median(arr) {
    if (!arr.length) return null;
    const s = sorted(arr);
    const mid = Math.floor(s.length / 2);
    return s.length % 2 === 0 ? (s[mid - 1] + s[mid]) / 2 : s[mid];
}

function mode(arr) {
    if (!arr.length) return null;
    const counts = {};
    let best = null;
    let bestCount = 0;
    for (const v of arr) {
        const key = Number(v).toFixed(2);
        counts[key] = (counts[key] || 0) + 1;
        if (counts[key] > bestCount) {
            bestCount = counts[key];
            best = Number(key);
        }
    }
    return best;
}

function min(arr) { return arr.length ? Math.min(...arr) : null; }
function max(arr) { return arr.length ? Math.max(...arr) : null; }
function range(arr) {
    if (!arr.length) return null;
    return Math.max(...arr) - Math.min(...arr);
}

function correlation(xs, ys) {
    if (xs.length !== ys.length || xs.length < 2) return null;
    const mx = mean(xs);
    const my = mean(ys);
    let num = 0;
    let dx = 0;
    let dy = 0;
    for (let i = 0; i < xs.length; i++) {
        const a = xs[i] - mx;
        const b = ys[i] - my;
        num += a * b;
        dx += a * a;
        dy += b * b;
    }
    const den = Math.sqrt(dx * dy);
    return den ? num / den : null;
}

const grouped = {};
for (const r of rows) {
